from pathlib import Path
p=Path('client-dotnet/GatTelemetry/MainForm.cs')
s=p.read_text(encoding='utf-8')
field='        private RemoteVersion _availableUpdate;\n'
if '_latchedJob' not in s:
    s=s.replace(field,field+'        private JObject _latchedJob;\n        private string _latchedJobKey = string.Empty;\n',1)
read='                    JObject tele = await _telemetry.ReadAsync();\n                    _lastTelemetry = DateTime.UtcNow;\n'
if 'StabilizeJobTelemetry(tele)' not in s:
    s=s.replace(read,read+'                    tele = StabilizeJobTelemetry(tele);\n',1)
marker='        private string ChooseDriver(List<string> players)\n'
methods='''        private JObject StabilizeJobTelemetry(JObject tele)\n        {\n            if (tele == null) return null;\n            bool delivered = BoolAny(tele, "gameplay.jobDelivered", "jobDelivered");\n            bool cancelled = BoolAny(tele, "gameplay.jobCancelled", "jobCancelled", "gameplay.jobCanceled", "jobCanceled");\n            if (delivered || cancelled)\n            {\n                if (_latchedJob != null) ClientStore.Log((delivered ? "JOB DELIVERED | " : "JOB CANCELLED | ") + JobSummary(_latchedJob));\n                _latchedJob = null; _latchedJobKey = string.Empty; return tele;\n            }\n            string cargo = TextAny(tele, "cargo_name", "job.cargoName", "job.cargo");\n            string cargoId = TextAny(tele, "cargo_id", "job.cargoId", "Job.CargoId");\n            double mass = NumberAny(tele, "mass_kg", "cargoMass", "cargo_mass", "job.cargoMass", "Job.CargoMass");\n            double planned = NumberAny(tele, "planned_distance_km", "job.plannedDistanceKm", "Job.PlannedDistanceKm");\n            double remaining = NumberAny(tele, "remaining_km");\n            if (_latchedJob == null && (!string.IsNullOrWhiteSpace(cargo) || !string.IsNullOrWhiteSpace(cargoId)) && mass > 0)\n            {\n                _latchedJob = new JObject();\n                CopyValue(tele,_latchedJob,"cargo_name","cargo_name","job.cargoName","job.cargo");\n                CopyValue(tele,_latchedJob,"cargo_id","cargo_id","job.cargoId","Job.CargoId");\n                CopyValue(tele,_latchedJob,"mass_kg","mass_kg","cargoMass","cargo_mass","job.cargoMass","Job.CargoMass");\n                CopyValue(tele,_latchedJob,"source_city","source_city","job.sourceCity");\n                CopyValue(tele,_latchedJob,"destination_city","destination_city","job.destinationCity");\n                _latchedJob["planned_distance_km"] = planned > 0 ? planned : remaining;\n                _latchedJob["job_latched"] = true;\n                _latchedJobKey = !string.IsNullOrWhiteSpace(cargoId) ? cargoId : cargo + "|" + mass.ToString("0");\n                ClientStore.Log("JOB STARTED | " + JobSummary(_latchedJob));\n            }\n            if (_latchedJob != null)\n            {\n                foreach (var x in _latchedJob.Properties()) if (tele[x.Name] == null || string.IsNullOrWhiteSpace(tele[x.Name].ToString())) tele[x.Name] = x.Value.DeepClone();\n                tele["on_job"] = true; tele["job_latched"] = true; tele["job_latch_key"] = _latchedJobKey;\n            }\n            return tele;\n        }\n        private static void CopyValue(JObject a,JObject b,string output,params string[] paths){foreach(string path in paths){var t=a.SelectToken(path,false);if(t!=null&&t.Type!=JTokenType.Null&&!string.IsNullOrWhiteSpace(t.ToString())){b[output]=t.DeepClone();return;}}}\n        private static string TextAny(JObject a,params string[] paths){foreach(string path in paths){var t=a.SelectToken(path,false);if(t!=null&&t.Type!=JTokenType.Null&&!string.IsNullOrWhiteSpace(t.ToString()))return t.ToString().Trim();}return string.Empty;}\n        private static double NumberAny(JObject a,params string[] paths){foreach(string path in paths){var t=a.SelectToken(path,false);double n;if(t!=null&&double.TryParse(t.ToString(),System.Globalization.NumberStyles.Any,System.Globalization.CultureInfo.InvariantCulture,out n))return n;}return 0;}\n        private static bool BoolAny(JObject a,params string[] paths){foreach(string path in paths){var t=a.SelectToken(path,false);bool b;if(t!=null&&((bool.TryParse(t.ToString(),out b)&&b)||t.ToString()=="1"))return true;}return false;}\n        private static string JobSummary(JObject a){return TextAny(a,"cargo_name")+" | "+NumberAny(a,"mass_kg").ToString("0")+" kg | "+NumberAny(a,"planned_distance_km").ToString("0.0")+" km | "+TextAny(a,"source_city")+" > "+TextAny(a,"destination_city");}\n\n'''
if 'private JObject StabilizeJobTelemetry' not in s:
    if marker not in s: raise SystemExit('ChooseDriver nao encontrado')
    s=s.replace(marker,methods+marker,1)
if 'private const string CurrentVersion = "1.0.22";' not in s: raise SystemExit('versao 1.0.22 nao encontrada')
s=s.replace('private const string CurrentVersion = "1.0.22";','private const string CurrentVersion = "1.0.23";',1).replace('GAT Telemetria C# 1.0.22 TESTE','GAT Telemetria C# 1.0.23 TESTE').replace('C# WinForms 1.0.22','C# WinForms 1.0.23')
p.write_text(s,encoding='utf-8')
proj=Path('client-dotnet/GatTelemetry/GatTelemetry.csproj'); proj.write_text(proj.read_text(encoding='utf-8').replace('1.0.22.0','1.0.23.0'),encoding='utf-8')
ip=Path('client-dotnet/GatTelemetryInstaller/GatTelemetryInstaller.csproj'); ip.write_text(ip.read_text(encoding='utf-8').replace('GAT_TELEMETRIA_DOTNET_UPDATE_1.0.22_CARGOID_KM_TESTE','GAT_TELEMETRIA_DOTNET_UPDATE_1.0.23_JOB_LATCH_TESTE'),encoding='utf-8')
inst=Path('client-dotnet/GatTelemetryInstaller/Program.cs'); q=inst.read_text(encoding='utf-8').replace('Atualizar GAT Telemetria para 1.0.22?','Atualizar GAT Telemetria para 1.0.23?').replace('GAT Telemetria C# 1.0.22 atualizado.','GAT Telemetria C# 1.0.23 atualizado.'); inst.write_text(q,encoding='utf-8')
print('1.0.23 job latch aplicado')
